 <section class="player-quick-grid"><article><small>Equipo</small><b>${esc(team?.name||"Aún sin equipo")}</b></article><article><small>Posición</small><b>${esc(p.positionName||"Por definir")}</b></article><article><small>Valoración general</small><b>${p.overall??"Pendiente de evaluación"}</b></article><article><small>Temporada</small><b>${esc(team?.season||"Sin temporada")}</b></article></section>
