async function playerNextMatchPage(){
 const team=await currentPlayerTeam();if(!team)return `<section class="player-section-head"><div><span class="eyebrow green">CALENDARIO</span><h1>Siguiente partido</h1><p>La alineación de tu equipo y la del próximo rival.</p></div></section>${emptyPlayer("Primero necesitas pertenecer a un equipo para consultar sus partidos.")}`;
 const s=await getDocs(query(collection(db,"matches"),where("status","in",["scheduled","published"]),limit(100))).catch(()=>({docs:[]}));
 const m=s.docs.map(d=>({id:d.id,...d.data()})).filter(x=>x.homeTeamId===team.id||x.awayTeamId===team.id).sort((a,b)=>(a.kickoff?.seconds||0)-(b.kickoff?.seconds||0))[0];
 if(!m)return `<section class="player-section-head"><div><span class="eyebrow green">CALENDARIO</span><h1>Siguiente partido</h1></div></section>${emptyPlayer("Tu equipo todavía no tiene un siguiente partido programado.")}`;
 const home=m.homeTeamId===team.id,opponent=home?m.awayTeam:m.homeTeam,oppId=home?m.awayTeamId:m.homeTeamId,opp=oppId?await getDoc(doc(db,"teams",oppId)).catch(()=>null):null,op=opp?.exists()?opp.data():{};
 const kickoff=m.kickoff?.toDate?m.kickoff.toDate().toLocaleString("es-MX"):"Fecha por confirmar";
 const lineup=(label,players,captainPhoto,captainName)=>`<div class="lineup-card"><div class="captain-strip"><img src="${esc(captainPhoto||"./assets/player-placeholder.svg")}" onerror="this.src='./assets/player-placeholder.svg'"><div><small>CAPITÁN</small><b>${esc(captainName||"Por confirmar")}</b></div></div><h3>${esc(label)}</h3><table><thead><tr><th>Dorsal</th><th>Pos.</th><th>Jugador</th></tr></thead><tbody>${(players||[]).map(x=>`<tr><td>${esc(x.number??"—")}</td><td>${esc(x.positionCode||"—")}</td><td>${esc(x.name||x.displayName||"Por confirmar")}</td></tr>`).join("")||'<tr><td colspan="3">Alineación pendiente de publicar</td></tr>'}</tbody></table></div>`;
 return `<section class="player-section-head"><div><span class="eyebrow green">PRÓXIMO ENCUENTRO</span><h1>Siguiente partido</h1><p>${esc(kickoff)}</p></div></section><div class="match-faceoff"><img src="${esc(team.logoURL||"./assets/club-placeholder.svg")}"><div><b>${esc(team.name)}</b><small>VS</small><b>${esc(op.name||opponent||"Rival")}</b></div><img src="${esc(op.logoURL||"./assets/club-placeholder.svg")}"></div><div class="lineup-duo">${lineup(team.name,m.homeLineup||m.lineupHome,m.homeCaptainPhotoURL||team.captainPhotoURL,m.homeCaptainName||team.captainName)}${lineup(op.name||opponent||"Rival",m.awayLineup||m.lineupAway,m.awayCaptainPhotoURL||op.captainPhotoURL,m.awayCaptainName||op.captainName)}</div><div class="player-panel"><b>Distribución en el campo</b><p>La pizarra táctica estará disponible cuando el cuerpo técnico publique la alineación y formación del encuentro.</p><button class="btn-secondary" disabled>Consultar distribución · Próximamente</button></div>`;
}
